import {ButtonSize} from '@gravity-ui/uikit';

import {GridColumnSize, GridColumnSizesType, IndentValue} from '../../grid/types';
import {ThemeSupporting} from '../../utils';
import {DeviceSupporting} from '../../utils/breakpoint';
import {AnalyticsEventsBase, AnalyticsEventsProp} from '../common';

import {
    AnchorProps,
    Animatable,
    BackgroundImageProps,
    ButtonProps,
    CardBorder,
    ContentSize,
    ContentTextSize,
    ContentTheme,
    FileLinkProps,
    GravityIconProps,
    HeaderBreadCrumbsProps,
    HeaderImageSize,
    HeaderOffset,
    HeaderWidth,
    ImageDeviceProps,
    ImageProps,
    Justify,
    LegendTableMarkerType,
    LinkProps,
    MapProps,
    MediaComponentImageProps,
    MediaComponentVideoProps,
    MediaDirection,
    MediaProps,
    MediaView,
    TextSize,
    TextTheme,
    ThemedImage,
    ThemedMediaProps,
    ThemedMediaVideoProps,
    TitleItemBaseProps,
    TitleItemProps,
    WithBorder,
    YandexFormProps,
} from './common';
import {BannerCardProps, HubspotFormProps, SubBlock, SubBlockModels} from './sub-blocks';

export enum BlockType {
    PromoFeaturesBlock = 'promo-features-block',
    ExtendedFeaturesBlock = 'extended-features-block',
    /** @deprecated */
    SliderOldBlock = 'slider-old-block',
    SliderBlock = 'slider-block',
    QuestionsBlock = 'questions-block',
    FoldableListBlock = 'foldable-list-block',
    BannerBlock = 'banner-block',
    CompaniesBlock = 'companies-block',
    MediaBlock = 'media-block',
    InfoBlock = 'info-block',
    TableBlock = 'table-block',
    TabsBlock = 'tabs-block',
    HeaderSliderBlock = 'header-slider-block',
    HeaderBlock = 'header-block',
    HeroBlock = 'hero-block',
    IconsBlock = 'icons-block',
    CardLayoutBlock = 'card-layout-block',
    ContentLayoutBlock = 'content-layout-block',
    ShareBlock = 'share-block',
    MapBlock = 'map-block',
    FilterBlock = 'filter-block',
    FormBlock = 'form-block',
    FooterBlock = 'footer-block',
}

export const BlockTypes = Object.values(BlockType);
export const HeaderBlockTypes = [
    BlockType.HeaderBlock,
    BlockType.HeaderSliderBlock,
    BlockType.HeroBlock,
];

export interface Childable {
    children?: SubBlock[];
}

//block props
export interface BlockBaseProps {
    anchor?: AnchorProps;
    visible?: GridColumnSize | Partial<Record<GridColumnSize, boolean>>;
    /** @deprecated */
    resetPaddings?: boolean;
    indent?: {
        top?: IndentValue;
        bottom?: IndentValue;
    };
    qa?: string;
}

export interface LoadableProps {
    source: string;
    /**
     * @deprecated Will be moved to params
     */
    serviceId?: number;
    params?: Record<string, string | number | boolean | object>;
}

export interface LoadableChildren {
    loadable?: LoadableProps;
}

export enum SliderBreakpointNames {
    Sm = 'sm',
    Md = 'md',
    Lg = 'lg',
    Xl = 'xl',
}

export enum SliderType {
    MediaCard = 'media-card',
    HeaderCard = 'header-card',
    FullscreenCard = 'fullscreen-card',
}

export type SliderBreakpointParams = Record<SliderBreakpointNames, number>;
export type SlidesToShow = Partial<SliderBreakpointParams> | number;

export interface SliderOldProps extends Childable, Animatable, LoadableChildren {
    dots?: boolean;
    arrows?: boolean;
    slidesToShow?: SlidesToShow;
    disclaimer?: {
        text: string;
        size?: TextSize;
    };
    title?: TitleItemBaseProps | string;
    description?: string;
    autoplay?: number;
    //for server transforms
    randomOrder?: boolean;
    adaptive?: boolean;
}

export interface SliderProps extends Childable, Animatable, LoadableChildren {
    dots?: boolean;
    arrows?: boolean;
    slidesToShow?: SlidesToShow;
    disclaimer?: {
        text: string;
        size?: TextSize;
    };
    title?: TitleItemBaseProps | string;
    description?: string;
    autoplay?: number;
    //for server transforms
    randomOrder?: boolean;
    adaptive?: boolean;
}

export interface HeaderSliderBlockProps extends Omit<SliderOldProps, 'title' | 'description'> {
    items: HeaderBlockProps[];
}

interface HeaderBackgroundProps {
    /** @deprecated replaced by Media Props image */
    url?: string;
    /** @deprecated replaced by Media Props image */
    disableCompress?: boolean;
}

export interface HeaderBlockBackground extends Partial<HeaderBackgroundProps>, Partial<MediaProps> {
    fullWidth?: boolean;
    fullWidthMedia?: boolean;
}

export type ThemedHeaderBlockBackground = ThemeSupporting<HeaderBlockBackground>;

export interface HeaderBlockVideoIframe {
    src: string;
    autoplay?: boolean;
    previewImg?: string;
    height?: number;
}

export interface HeaderBlockProps {
    title: string;
    overtitle?: string | JSX.Element;
    description?: string;
    additionalInfo?: string;
    buttons?: Pick<ButtonProps, 'url' | 'text' | 'theme' | 'primary' | 'size' | 'extraProps'>[];
    width?: HeaderWidth;
    /** @deprecated imageSize now depends on width */
    imageSize?: HeaderImageSize;
    /**
     * @deprecated used only on the main page
     * TODO: delete after the possibility to remove padding-bottom in the block
     */
    offset?: HeaderOffset;
    image?: ThemedImage;
    video?: ThemedMediaVideoProps;
    videoIframe?: HeaderBlockVideoIframe;
    mediaView?: MediaView;
    centered?: boolean;
    background?: ThemedHeaderBlockBackground;
    theme?: 'light' | 'dark';
    verticalOffset?: '0' | 's' | 'm' | 'l' | 'xl';
    breadcrumbs?: HeaderBreadCrumbsProps;
    status?: JSX.Element;
    renderTitle?: (title: string) => React.ReactNode;
}

export interface HeroBlockBackground
    extends Partial<MediaComponentImageProps>,
        Partial<MediaComponentVideoProps> {
    color?: string;
}

export interface HeroBlockMedia extends Partial<MediaProps> {
    roundCorners?: boolean;
}

export interface HeroBlockContent
    extends Pick<ContentBlockProps, 'text' | 'list' | 'additionalInfo' | 'links' | 'theme'> {
    title: Required<ContentBlockProps>['title'];
}

export interface HeroBlockProps extends HeroBlockContent {
    breadcrumbs?: HeaderBreadCrumbsProps;
    // TODO: add overtitle to ContentProps
    overtitle?: string | JSX.Element;
    /** Buttons are always rendered at size `xl` — a per-button `size` has no effect. */
    buttons?: ThemeSupporting<
        | Pick<
              ButtonProps,
              'url' | 'text' | 'theme' | 'primary' | 'extraProps' | 'target' | 'analyticsEvents'
          >
        | React.ReactNode
    >[];
    media?: ThemeSupporting<HeroBlockMedia>;
    fullWidth?: boolean;
    verticalOffset?: 's' | 'm' | 'l' | 'xl';
    background?: ThemeSupporting<HeroBlockBackground>;
}

export interface ExtendedFeaturesItem
    extends Omit<
        ContentBlockProps,
        'title' | 'theme' | 'centered' | 'colSizes' | 'size' | 'title'
    > {
    title?: string;
    label?: string;
    icon?: ThemedImage;
    /** @deprecated **/
    link?: LinkProps;
}

export interface ExtendedFeaturesProps extends Animatable {
    items: ExtendedFeaturesItem[];
    title?: TitleItemProps | string;
    description?: string;
    colSizes?: GridColumnSizesType;
}

export interface PromoFeaturesItem {
    title: string;
    text: string;
    theme?: 'accent' | 'accent-light' | 'primary';
    media?: ThemeSupporting<MediaProps>;
}

export interface PromoFeaturesProps extends Animatable {
    items: PromoFeaturesItem[];
    title?: TitleItemProps | string;
    description?: string;
    theme?: 'grey' | 'default';
}

export interface QuestionItem {
    title: string;
    text: string;
    listStyle?: 'dash' | 'disk';
    link?: LinkProps;
    onClick?: (index: number, newOpenState: boolean) => void;
}

export interface QuestionsProps
    extends Omit<ContentBlockProps, 'colSizes' | 'centered' | 'size' | 'theme'> {
    items: QuestionItem[];
}

export interface QuestionBlockItemProps extends QuestionItem {
    isOpened: boolean;
    onClick: () => void;
}

export interface FoldableListItem {
    title: string;
    text: string;
    listStyle?: 'dash' | 'disk';
    link?: LinkProps;
}

export interface FoldableListProps
    extends Omit<ContentBlockProps, 'colSizes' | 'centered' | 'size' | 'theme'> {
    items: FoldableListItem[];
}

export interface FoldableListBlockItemProps extends FoldableListItem {
    isOpened: boolean;
    onClick: () => void;
}

export interface BannerBlockProps extends BannerCardProps, Animatable {}

export interface CompaniesBlockProps extends Animatable {
    title: string;
    description?: string;
    images: ThemeSupporting<ImageDeviceProps>;
}

export interface MediaBaseBlockProps extends Animatable, MediaContentProps {
    direction?: MediaDirection;
    mobileDirection?: MediaDirection;
    largeMedia?: boolean;
    mediaOnly?: boolean;
    mediaOnlyColSizes?: GridColumnSizesType;
}

export interface MediaContentProps
    extends Omit<ContentBlockProps, 'colSizes' | 'text' | 'theme' | 'centered'> {
    description?: string;
    /** @deprecated  Use array of buttons from ContentBlockProps instead**/
    button?: ButtonProps;
}

export interface MediaBlockProps extends MediaBaseBlockProps, WithBorder {
    media: ThemeSupporting<MediaProps>;
}

export interface MapBlockProps extends MediaBaseBlockProps, WithBorder {
    map: Omit<MapProps, 'forceAspectRatio' | 'areaMargin' | 'copyrightPosition'>;
}

export interface InfoBlockProps {
    theme?: TextTheme;
    backgroundColor?: ThemeSupporting<string>;
    /** @deprecated **/
    title?: string;
    /** @deprecated **/
    buttons?: Pick<ButtonProps, 'url' | 'text' | 'theme'>[];
    /** @deprecated **/
    sectionsTitle?: string;
    /** @deprecated **/
    links?: Pick<LinkProps, 'text' | 'url'>[];
    leftContent?: Omit<ContentBlockProps, 'colSizes' | 'theme' | 'size'>;
    rightContent?: Omit<ContentBlockProps, 'colSizes' | 'theme' | 'size'>;
}

export interface TableProps {
    content: string[][];
    legend?: string[];
    hideLegend?: boolean;
    justify?: Justify[];
    marker?: LegendTableMarkerType;
    /**
     * Only as accessible name, not displayed explicitly
     */
    caption?: string;
}

export interface TableBlockProps {
    title: string;
    table: TableProps;
}

export interface TabsBlockItem
    extends Omit<ContentBlockProps, 'size' | 'colSizes' | 'centered' | 'theme'>,
        WithBorder {
    tabName: string;
    /**
     * @deprecated Use array links from ContentBlockProps instead
     */
    link?: LinkProps;
    image?: ThemedImage;
    caption?: string;
    media?: ThemedMediaProps;
}

export interface TabsBlockProps extends Animatable {
    title?: TitleItemProps | string;
    description?: string;
    tabsColSizes?: GridColumnSizesType;
    centered?: boolean;
    direction?: MediaDirection;
    items: TabsBlockItem[];
    contentSize?: ContentSize;
}

export interface CardLayoutBlockProps extends Childable, Animatable, LoadableChildren {
    title?: TitleItemProps | string;
    titleClassName?: string;
    centered?: boolean;
    description?: string;
    colSizes?: GridColumnSizesType;
    background?: ThemeSupporting<
        BackgroundImageProps & {
            border?: CardBorder;
        }
    >;
}

export type FilterTag = {
    collapsible?: boolean;
    id: string;
    label: string;
    analyticsEvent?: AnalyticsEventsProp;
};

export type FilterItem = {
    tags: string[];
    card: SubBlockModels;
};

export interface FilterBlockProps extends Animatable {
    visibleRowsCount?: Partial<Record<GridColumnSize, number>>;
    expandButtonText?: string;
    collapseButtonText?: string;
    tags: FilterTag[];
    items: FilterItem[];
    title?: TitleItemProps | string;
    description?: string;
    tagButtonSize?: ButtonSize;
    allTag?: boolean | string | FilterTag;
    colSizes?: GridColumnSizesType;
    centered?: boolean;
}

export interface IconsBlockItemProps extends AnalyticsEventsBase {
    url?: string;
    text?: string;
    src: ThemeSupporting<string>;
}

export interface IconsBlockProps {
    title?: string;
    description?: string;
    size?: 's' | 'm' | 'l';
    items: IconsBlockItemProps[];
    colSizes?: GridColumnSizesType;
}

interface ContentLayoutBlockParams {
    size?: ContentSize;
    background?: ThemeSupporting<BackgroundImageProps>;
    centered?: boolean;
    theme?: ContentTheme;
    textWidth?: ContentTextSize;
}

export interface ContentLayoutBlockProps extends ContentLayoutBlockParams {
    textContent: ContentBlockProps;
    fileContent?: FileLinkProps[];
}

export type SVGIcon = (props: React.SVGProps<SVGSVGElement>) => React.ReactNode;

export interface ContentItemProps {
    title?: string;
    text?: string;
    icon?: ThemeSupporting<ImageProps | SVGIcon>;
    gravityIcon?: ThemeSupporting<GravityIconProps>;
}

export interface ContentListProps {
    list: ContentItemProps[];
    size: ContentSize;
    theme?: ContentTheme;
}

export interface ContentBlockProps {
    title?: TitleItemBaseProps | string;
    titleId?: string;
    text?: string;
    textId?: string;
    additionalInfo?: string;
    links?: LinkProps[];
    buttons?: (ButtonProps | React.ReactNode)[];
    size?: ContentSize;
    colSizes?: GridColumnSizesType;
    centered?: boolean;
    theme?: ContentTheme;
    list?: ContentItemProps[];
    controlPosition?: 'default' | 'bottom';
}

export enum PCShareSocialNetwork {
    Vk = 'vk',
    Telegram = 'telegram',
    Twitter = 'twitter',
    Facebook = 'facebook',
    LinkedIn = 'linkedin',
}

export interface ShareBlockProps {
    items: PCShareSocialNetwork[];
    title?: string;
}

export enum FormBlockDataTypes {
    YANDEX = 'yandex',
    HUBSPOT = 'hubspot',
}

export enum FormBlockDirection {
    FormContent = 'form-content',
    ContentForm = 'content-form',
    Center = 'center',
}

export interface FormBlockYandexData {
    yandex: ThemeSupporting<YandexFormProps>;
}

export interface FormBlockHubspotData {
    hubspot: ThemeSupporting<HubspotFormProps>;
}

export type FormBlockData = FormBlockYandexData | FormBlockHubspotData;

export interface FormBlockBackgroundProps extends Omit<BackgroundImageProps, 'style'> {
    style?: DeviceSupporting<React.CSSProperties>;
}

export interface FormBlockProps {
